// Say hello to the console!
console.log("Hello, world!");

// JavaScript powers interactive websites.

const name = "Ada";
let score = 0;

score = score + 1;
console.log(name, score);

const subtotal = 12 + 8;
const hasDiscount = subtotal >= 20;
const total = hasDiscount ? subtotal - 2 : subtotal;

console.log(total); // 18

const username = "";
const displayName = username || "Guest";

if (displayName) {
  console.log(`Welcome, ${displayName}!`);
}

const learner = "Sam";
const topic = "JavaScript";
const greeting = `Hi ${learner},
let’s learn ${topic}!`;

console.log(greeting);

const temperature = 23;

if (temperature > 30) {
  console.log("Stay cool!");
} else {
  console.log("Enjoy the day!");
}

const colors = ["blue", "gold", "teal"];

for (const color of colors) {
  console.log(color);
}

const fruits = ["pear", "mango"];
fruits.push("plum");

console.log(fruits[0]);       // "pear"
console.log(fruits.length);   // 3

const book = {
  title: "Small Steps",
  pages: 120
};

console.log(book.title);
book.pages = 128;

const tags = new Set(["js", "web", "js"]);
const scores = new Map();
scores.set("Ada", 95);

console.log(tags.size);       // 2
console.log(scores.get("Ada")); // 95

const user = { name: "Mina", active: true };
const text = JSON.stringify(user);
const restored = JSON.parse(text);

console.log(restored.name); // "Mina"

function greet(name) {
  return `Hello, ${name}!`;
}

const message = greet("Rae");
console.log(message);

const double = (number) => number * 2;
const numbers = [1, 2, 3];
const doubled = numbers.map(double);

console.log(doubled); // [2, 4, 6]

function makeCounter() {
  let count = 0;
  return () => ++count;
}

const next = makeCounter();
console.log(next()); // 1
console.log(next()); // 2

const scores = [8, 12, 15, 6];
const passing = scores.filter(score => score >= 10);
const doubled = passing.map(score => score * 2);

console.log(doubled); // [24, 30]

try {
  JSON.parse("{bad json}");
} catch (error) {
  console.error("Could not read data:", error.message);
}

const heading = document.querySelector("h1");

if (heading) {
  heading.textContent = "Hello, DOM!";
}

const button = document.querySelector("button");

button?.addEventListener("click", () => {
  console.log("Thanks for clicking!");
});

const item = document.createElement("li");
item.textContent = "Practice JavaScript";

document.querySelector("ul")?.append(item);

// math.js
export const add = (a, b) => a + b;

// app.js
import { add } from "./math.js";
console.log(add(2, 3));

const user = { name: "Jo", level: 3 };
const { name, level } = user;
const upgraded = { ...user, level: level + 1 };

console.log(name, upgraded.level);

async function loadMessage() {
  try {
    const response = await fetch("/api/hello");
    const data = await response.json();
    console.log(data);
  } catch (error) {
    console.error("Loading failed:", error);
  }
}

console.log("first");
setTimeout(() => console.log("timer"), 0);
Promise.resolve().then(() => console.log("promise"));
console.log("last");
// first → last → promise → timer

async function loadItems() {
  const response = await fetch("/api/items");
  if (!response.ok) {
    throw new Error(`HTTP ${response.status}`);
  }
  const items = await response.json();
  console.log(items);
}

loadItems();

class Pet {
  constructor(name) {
    this.name = name;
  }
  speak() {
    return `${this.name} says hi!`;
  }
}

console.log(new Pet("Mochi").speak());

const player = {
  name: "Kai",
  sayName() {
    return this.name;
  }
};

console.log(player.sayName()); // "Kai"

const settings = { theme: "light" };
localStorage.setItem("settings", JSON.stringify(settings));

const saved = localStorage.getItem("settings");
const restored = saved ? JSON.parse(saved) : null;

// In a project with a package.json:
// npm install
// npm run dev

console.log("Build, test, and inspect as you learn.");

const form = document.querySelector("#signup");

form.addEventListener("submit", (event) => {
  event.preventDefault();
  const data = new FormData(form);
  const name = String(data.get("name") || "").trim();
  console.log(name ? `Welcome, ${name}!` : "Please enter your name.");
});

